import{z as d,x as B,o,c as A,q as s,j as l,D as t,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"粘包与帧定界","description":"","frontmatter":{"title":"粘包与帧定界","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/message-framing.md","filePath":"cs/message-framing.md","lastUpdated":1791413859000}'),p={name:"cs/message-framing.md"};function c(m,a,P,h,C,u){const E=B("Mermaid");return o(),A("div",null,[a[2]||(a[2]=s('<h1 id="粘包与帧定界" tabindex="-1">粘包与帧定界 <a class="header-anchor" href="#粘包与帧定界" aria-label="Permalink to &quot;粘包与帧定界&quot;">​</a></h1><div class="epigraph"><p>TCP 是字节流，两次 `write` 可并成一次 `read`；应用必须自己定界：长度前缀、分隔符或自描述编码。</p><footer>—— 据 RFC 9293 字节流；Stevens UNP；Protobuf/gRPC 帧对照整理</footer></div><p><a href="/cs/serialization-protobuf">序列化</a> 产出消息。<a href="/cs/reactor-proactor">Reactor</a> 一次可读任意字节。<a href="/cs/c10k-concurrency">上一课</a> 不保证消息边界。缺口是<strong>成帧</strong>：粘包、拆包、缓冲。本课不把心跳写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UDP 有报文边界（仍可能丢/乱序）。TCP 无。JSON 无长度时要括号配对，危险。常见：4 字节长度 + 体；WebSocket 已有帧；gRPC 有 5 字节前缀；HTTP/1.1 用 Content-Length/chunked。TSO 把大缓冲切开，接收 GRO 再粘，应用仍要定界。SSH 与 TLS 记录层自己成帧。</p><p>不要用 <code>sleep</code> 当定界。</p><p><span class="marginnote">术语翻译：粘包不是 bug，而是 TCP 按「字节流」交付的正常行为——它只保证字节不丢不重，不保留你 <code>write</code> 时的条数边界；一次 <code>write</code> 可能被拆成多次 <code>read</code>，两次 <code>write</code> 也可能被并成一次 <code>read</code>，所以应用层必须自带定界结构。</span></p><p><span class="marginnote">常见误区：以为「<code>sleep</code> 一秒再 <code>read</code> 就能收完整条消息」。延迟不产生边界，网络一抖照样截断，还白加了延迟；定界只能靠长度前缀、分隔符或记录层这类显式结构。</span></p><p><span class="marginnote">UNP 强调。本课不发明私有协议细节。</span></p><h3 id="字节流无消息" tabindex="-1">字节流无消息 <a class="header-anchor" href="#字节流无消息" aria-label="Permalink to &quot;字节流无消息&quot;">​</a></h3><p>长度前缀或记录层定界。sleep 不是帧。最大长度要帽。SCTP/UDP 有边界是对照不是 TCP 的性质。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三种定界。画：读循环 → 缓冲 → 切消息 → handler。与线路码逗号对齐同构，一层 PHY，一层应用。</p>',13)),(o(),l(i,null,{default:t(()=>[n(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22TCP%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20BUF%5B%22%E5%BA%94%E7%94%A8%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%E5%89%8D%E7%BC%80%E5%88%87%22%5D%0A%20%20BUF%20--%3E%20DELIM%5B%22%E5%88%86%E9%9A%94%E7%AC%A6%E5%88%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"部分读：非阻塞下必循环。最大长度要帽，防内存炸弹。QUIC 流有流内偏移，仍要应用帧若多消息。SCTP 消息边界是对照。PMTUD 不解决粘包。",-1)),a[5]||(a[5]=e("p",null,"安全：长度字段过大是 DoS。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[r("数字实例：长度前缀若不限帽，攻击者发 4 字节声称「本帧 0xFFFFFFFF 字节」（约 43 亿），服务器一分配就被内存炸弹打爆；先判 "),e("code",null,"len \\gt 上限"),r("（如 16 MiB）就拒绝，是成帧代码的固定动作。")])],-1)),(o(),l(i,null,{default:t(()=>[n(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20READ%5B%22read%20%E5%88%B0%E4%BB%BB%E6%84%8F%E4%B8%AA%E5%AD%97%E8%8A%82%22%5D%20--%3E%20APP%5B%22%E8%BF%BD%E5%8A%A0%E8%BF%9B%E5%BA%94%E7%94%A8%E7%BC%93%E5%86%B2%22%5D%0A%20%20APP%20--%3E%20HAVE%7B%22%E7%BC%93%E5%86%B2%E9%87%8C%E5%87%91%E9%BD%90%E4%B8%80%E6%9D%A1%E5%AE%8C%E6%95%B4%E6%B6%88%E6%81%AF%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20HAVE%20--%3E%7C%22%E4%B8%8D%E5%A4%9F%22%7C%20WAIT%5B%22%E5%9B%9E%E5%88%B0%E4%BA%8B%E4%BB%B6%E5%BE%AA%E7%8E%AF%E7%AD%89%E4%B8%8B%E6%AC%A1%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20HAVE%20--%3E%7C%22%E5%A4%9F%E4%BA%86%22%7C%20CUT%5B%22%E5%88%87%E5%87%BA%E4%B8%80%E6%9D%A1%E4%BA%A4%E7%BB%99%20handler%22%5D%0A%20%20CUT%20--%3E%20LOOP%5B%22%E5%89%A9%E4%BD%99%E5%AD%97%E8%8A%82%E7%95%99%E5%9C%A8%E7%BC%93%E5%86%B2%E7%BB%A7%E7%BB%AD%E5%88%87%22%5D%0A%20%20LOOP%20--%3E%20HAVE%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ASN.1 TLV 的全部。心跳与超时是下一课。后课默认：字节流必须应用成帧。</p><p>把「一条 write 一条 read」当定理，在负载下必碎。</p><p>下一课<a href="/cs/heartbeat-timeout">心跳与超时</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCP 粘/拆包是正常。</li><li>长度、分隔或记录层定界。</li><li>读循环 + 上限缓冲。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；UNP。</li></ul>',6))])}const f=d(p,[["render",c]]);export{T as __pageData,f as default};
